import React, { useState, useEffect } from 'react';
import { checkAppHealth, checkDatabaseHealth, HealthResponse, DbHealthResponse } from '../services/api';
import { RefreshCw, Server, XCircle, Clock } from 'lucide-react';
import { config } from '../core/config';

export const HealthStatus: React.FC = () => {
  const [appStatus, setAppStatus] = useState<'checking' | 'connected' | 'unavailable'>('checking');
  const [dbStatus, setDbStatus] = useState<'checking' | 'connected' | 'unavailable'>('checking');
  const [appData, setAppData] = useState<HealthResponse | null>(null);
  const [dbData, setDbData] = useState<DbHealthResponse | null>(null);
  const [lastChecked, setLastChecked] = useState<string | null>(null);
  const [isRefreshing, setIsRefreshing] = useState(false);

  const performChecks = async () => {
    setIsRefreshing(true);
    setAppStatus('checking');
    setDbStatus('checking');

    try {
      const appRes = await checkAppHealth();
      setAppData(appRes);
      setAppStatus(appRes.status === 'ok' ? 'connected' : 'unavailable');
    } catch {
      setAppData(null);
      setAppStatus('unavailable');
    }

    try {
      const dbRes = await checkDatabaseHealth();
      setDbData(dbRes);
      setDbStatus(dbRes.status === 'ok' ? 'connected' : 'unavailable');
    } catch {
      setDbData(null);
      setDbStatus('unavailable');
    }

    setLastChecked(new Date().toLocaleTimeString());
    setIsRefreshing(false);
  };

  useEffect(() => {
    performChecks();
    const interval = setInterval(performChecks, 15000);
    return () => clearInterval(interval);
  }, []);

  return (
    <div className="card">
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px' }}>
        <h2 className="card-title" style={{ margin: 0 }}>
          <Server size={20} color="#60a5fa" />
          Infrastructure Connectivity
        </h2>
        <button
          onClick={performChecks}
          disabled={isRefreshing}
          className="btn"
          title="Refresh connectivity status"
        >
          <RefreshCw size={14} className={isRefreshing ? 'pulse' : ''} />
          {isRefreshing ? 'Checking...' : 'Refresh'}
        </button>
      </div>

      <div className="status-grid">
        {/* Backend App Health */}
        <div className="status-item">
          <div className="status-info">
            <span className="status-label">FastAPI Backend</span>
            <span className="status-endpoint">/upi-api/v1/health</span>
          </div>
          <div>
            {appStatus === 'connected' && (
              <span className="status-pill connected">
                <span className="dot pulse" />
                Connected
              </span>
            )}
            {appStatus === 'unavailable' && (
              <span className="status-pill unavailable">
                <XCircle size={14} />
                Unavailable
              </span>
            )}
            {appStatus === 'checking' && (
              <span className="status-pill checking">
                <Clock size={14} />
                Checking
              </span>
            )}
          </div>
        </div>

        {/* PostgreSQL Database Health */}
        <div className="status-item">
          <div className="status-info">
            <span className="status-label">PostgreSQL Database</span>
            <span className="status-endpoint">/upi-api/v1/health/db</span>
          </div>
          <div>
            {dbStatus === 'connected' && (
              <span className="status-pill connected">
                <span className="dot pulse" />
                Connected
              </span>
            )}
            {dbStatus === 'unavailable' && (
              <span className="status-pill unavailable">
                <XCircle size={14} />
                Unavailable
              </span>
            )}
            {dbStatus === 'checking' && (
              <span className="status-pill checking">
                <Clock size={14} />
                Checking
              </span>
            )}
          </div>
        </div>
      </div>

      {/* Connection Metadata */}
      <table className="meta-table">
        <tbody>
          <tr>
            <td className="meta-key">Frontend Base Path</td>
            <td className="meta-val">{config.basePath}</td>
          </tr>
          <tr>
            <td className="meta-key">API Base URL</td>
            <td className="meta-val">{config.apiBaseUrl}</td>
          </tr>
          <tr>
            <td className="meta-key">Backend Reported App</td>
            <td className="meta-val">{appData?.app || '—'}</td>
          </tr>
          <tr>
            <td className="meta-key">Backend Environment</td>
            <td className="meta-val">{appData?.env || '—'}</td>
          </tr>
          <tr>
            <td className="meta-key">Database Status</td>
            <td className="meta-val">{dbData?.database || '—'}</td>
          </tr>
          <tr>
            <td className="meta-key">Last Inspected</td>
            <td className="meta-val">{lastChecked || 'Pending initial check'}</td>
          </tr>
        </tbody>
      </table>
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import {
  AlertCircle,
  CheckCircle2,
  ChevronLeft,
  ChevronRight,
  Clock,
  Eye,
  Filter,
  Loader2,
  RefreshCw,
  Search,
  XCircle,
} from 'lucide-react';
import { getCourses } from '../services/courseApi';
import { getBatches } from '../services/batchApi';
import { fetchAdminPayments, fetchAdminSubmittedPayments } from '../services/adminPaymentApi';
import { AdminPaymentFilterParams, AdminPaymentListItem } from '../types/adminPayment';
import { Course } from '../types/course';
import { Batch } from '../types/batch';

interface PaymentTableProps {
  fixedStatus?: string; // If set (e.g. 'SUBMITTED'), locks the status filter
  onNavigate: (path: string) => void;
  initialFilters?: AdminPaymentFilterParams;
}

export const PaymentTable: React.FC<PaymentTableProps> = ({
  fixedStatus,
  onNavigate,
  initialFilters,
}) => {
  const [items, setItems] = useState<AdminPaymentListItem[]>([]);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  // Pagination state
  const [page, setPage] = useState<number>(initialFilters?.page || 1);
  const [pageSize] = useState<number>(15);
  const [total, setTotal] = useState<number>(0);
  const [totalPages, setTotalPages] = useState<number>(0);

  // Filter states
  const [statusFilter, setStatusFilter] = useState<string>(
    fixedStatus || initialFilters?.status || ''
  );
  const [courseFilter, setCourseFilter] = useState<string>(
    initialFilters?.course_public_id || ''
  );
  const [batchFilter, setBatchFilter] = useState<string>(
    initialFilters?.batch_public_id || ''
  );
  const [searchInput, setSearchInput] = useState<string>(initialFilters?.search || '');
  const [appliedSearch, setAppliedSearch] = useState<string>(initialFilters?.search || '');

  // Catalog options for dropdown filters
  const [courses, setCourses] = useState<Course[]>([]);
  const [batches, setBatches] = useState<Batch[]>([]);

  useEffect(() => {
    async function loadCatalog() {
      try {
        const [cList, bList] = await Promise.all([
          getCourses().catch(() => []),
          getBatches().catch(() => []),
        ]);
        setCourses(cList);
        setBatches(bList);
      } catch {
        // Dropdowns will gracefully remain empty
      }
    }
    loadCatalog();
  }, []);

  const loadData = async () => {
    setLoading(true);
    setError(null);
    try {
      const filterParams: AdminPaymentFilterParams = {
        status: fixedStatus || statusFilter || undefined,
        course_public_id: courseFilter || undefined,
        batch_public_id: batchFilter || undefined,
        search: appliedSearch || undefined,
        page,
        page_size: pageSize,
      };

      const data = fixedStatus === 'SUBMITTED' && !statusFilter
        ? await fetchAdminSubmittedPayments(filterParams)
        : await fetchAdminPayments(filterParams);

      setItems(data.items);
      setTotal(data.total);
      setTotalPages(data.total_pages);
    } catch (err: any) {
      setError(err.message || 'Unable to load payment records.');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadData();
  }, [page, statusFilter, courseFilter, batchFilter, appliedSearch, fixedStatus]);

  const handleSearchSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setPage(1); // Reset to page 1 on new search
    setAppliedSearch(searchInput.trim());
  };

  const handleFilterChange = (
    setter: React.Dispatch<React.SetStateAction<string>>,
    value: string
  ) => {
    setPage(1); // Reset page to 1 on any filter change
    setter(value);
  };

  const clearFilters = () => {
    setPage(1);
    if (!fixedStatus) setStatusFilter('');
    setCourseFilter('');
    setBatchFilter('');
    setSearchInput('');
    setAppliedSearch('');
  };

  const formatINR = (val: number) => {
    return new Intl.NumberFormat('en-IN', {
      style: 'currency',
      currency: 'INR',
      maximumFractionDigits: 0,
    }).format(val);
  };

  const renderStatusBadge = (st: string) => {
    switch (st.toUpperCase()) {
      case 'PENDING':
        return (
          <span className="status-pill active-pill" style={{ fontSize: '0.75rem', padding: '3px 8px' }}>
            <Clock size={12} /> Awaiting Payment
          </span>
        );
      case 'SUBMITTED':
        return (
          <span className="status-pill status-pill-submitted" style={{ fontSize: '0.75rem', padding: '3px 8px' }}>
            <CheckCircle2 size={12} /> Submitted
          </span>
        );
      case 'APPROVED':
        return (
          <span className="status-pill" style={{ background: 'rgba(16, 185, 129, 0.2)', color: '#34d399', border: '1px solid rgba(16, 185, 129, 0.4)', fontSize: '0.75rem', padding: '3px 8px' }}>
            <CheckCircle2 size={12} /> Approved
          </span>
        );
      case 'REJECTED':
        return (
          <span className="status-pill" style={{ background: 'rgba(239, 68, 68, 0.15)', color: '#f87171', border: '1px solid rgba(239, 68, 68, 0.3)', fontSize: '0.75rem', padding: '3px 8px' }}>
            <XCircle size={12} /> Rejected
          </span>
        );
      case 'EXPIRED':
        return (
          <span className="status-pill archived-pill" style={{ fontSize: '0.75rem', padding: '3px 8px' }}>
            <Clock size={12} /> Expired
          </span>
        );
      default:
        return <span className="status-pill">{st}</span>;
    }
  };

  const hasActiveFilters =
    (statusFilter && statusFilter !== fixedStatus) ||
    courseFilter ||
    batchFilter ||
    appliedSearch;

  return (
    <div className="payment-table-container">
      {/* Search & Filter Bar */}
      <div className="card filter-bar-card" style={{ marginBottom: '1.5rem', padding: '16px' }}>
        <form onSubmit={handleSearchSubmit} className="filter-form-grid" style={{ display: 'grid', gridTemplateColumns: '2fr 1fr 1fr 1fr auto', gap: '12px', alignItems: 'center' }}>
          {/* Search Input */}
          <div className="search-input-wrapper" style={{ position: 'relative' }}>
            <Search size={16} style={{ position: 'absolute', left: '12px', top: '50%', transform: 'translateY(-50%)', color: '#94a3b8' }} />
            <input
              type="text"
              className="form-input"
              style={{ paddingLeft: '36px' }}
              placeholder="Search participant name, phone, email, Ref ID, or UTR..."
              value={searchInput}
              onChange={(e) => setSearchInput(e.target.value)}
            />
          </div>

          {/* Status Select */}
          {!fixedStatus ? (
            <select
              className="form-input filter-select"
              value={statusFilter}
              onChange={(e) => handleFilterChange(setStatusFilter, e.target.value)}
            >
              <option value="">All Statuses</option>
              <option value="PENDING">PENDING</option>
              <option value="SUBMITTED">SUBMITTED</option>
              <option value="APPROVED">APPROVED</option>
              <option value="REJECTED">REJECTED</option>
              <option value="EXPIRED">EXPIRED</option>
            </select>
          ) : (
            <div className="form-input filter-select disabled-input" style={{ opacity: 0.8, cursor: 'not-allowed', display: 'flex', alignItems: 'center' }}>
              <span>Status: {fixedStatus}</span>
            </div>
          )}

          {/* Course Select */}
          <select
            className="form-input filter-select"
            value={courseFilter}
            onChange={(e) => handleFilterChange(setCourseFilter, e.target.value)}
          >
            <option value="">All Courses</option>
            {courses.map((c) => (
              <option key={c.public_id} value={c.public_id}>
                {c.name}
              </option>
            ))}
          </select>

          {/* Batch Select */}
          <select
            className="form-input filter-select"
            value={batchFilter}
            onChange={(e) => handleFilterChange(setBatchFilter, e.target.value)}
          >
            <option value="">All Batches</option>
            {batches.map((b) => (
              <option key={b.public_id} value={b.public_id}>
                {b.name}
              </option>
            ))}
          </select>

          {/* Filter Actions */}
          <div style={{ display: 'flex', gap: '8px' }}>
            <button type="submit" className="btn btn-primary" style={{ padding: '8px 14px' }}>
              <Filter size={14} />
              <span>Search</span>
            </button>
            {hasActiveFilters && (
              <button
                type="button"
                onClick={clearFilters}
                className="btn btn-outline"
                style={{ padding: '8px 12px' }}
                title="Clear all active filters"
              >
                <span>Reset</span>
              </button>
            )}
          </div>
        </form>
      </div>

      {/* Main Table Card */}
      <div className="card" style={{ padding: '0', overflow: 'hidden' }}>
        {/* Card Header & Controls */}
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '16px 20px', borderBottom: '1px solid var(--border-color)' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
            <h2 style={{ fontSize: '1.05rem', fontWeight: 600 }}>Payment Sessions ({total})</h2>
            {loading && <Loader2 size={16} className="spinner" color="#818cf8" />}
          </div>
          <button
            onClick={loadData}
            disabled={loading}
            className="icon-btn"
            title="Refresh payment table"
          >
            <RefreshCw size={14} className={loading ? 'spinner' : ''} />
          </button>
        </div>

        {/* Loading / Error / Empty / Table render */}
        {error ? (
          <div className="error-banner" style={{ margin: '20px' }}>
            <AlertCircle size={16} color="#ef4444" />
            <span>{error}</span>
          </div>
        ) : loading && items.length === 0 ? (
          <div style={{ textAlign: 'center', padding: '3rem 0' }}>
            <Loader2 size={32} className="spinner" color="#818cf8" />
            <p style={{ color: '#94a3b8', fontSize: '0.9rem', marginTop: '0.5rem' }}>
              Loading payment records...
            </p>
          </div>
        ) : items.length === 0 ? (
          <div style={{ textAlign: 'center', padding: '3rem 1rem' }}>
            <p style={{ color: '#e2e8f0', fontSize: '1rem', fontWeight: 600 }}>No payments found.</p>
            <p style={{ color: '#94a3b8', fontSize: '0.875rem', marginTop: '0.25rem' }}>
              {hasActiveFilters ? 'Try adjusting or resetting your active search filters.' : 'No payment sessions exist in the system yet.'}
            </p>
            {hasActiveFilters && (
              <button onClick={clearFilters} className="btn btn-outline" style={{ marginTop: '1rem' }}>
                Clear Filters
              </button>
            )}
          </div>
        ) : (
          <div className="table-responsive">
            <table className="admin-table">
              <thead>
                <tr>
                  <th>Participant</th>
                  <th>Course & Batch</th>
                  <th>Amount</th>
                  <th>Reference ID</th>
                  <th>Current UTR</th>
                  <th>Status</th>
                  <th>Created At</th>
                  <th style={{ textAlign: 'right' }}>Action</th>
                </tr>
              </thead>
              <tbody>
                {items.map((item) => (
                  <tr key={item.payment_session_public_id}>
                    <td>
                      <div className="course-name-cell">
                        <span className="font-semibold" style={{ color: '#f8fafc' }}>{item.participant_name}</span>
                        <span className="course-desc-preview">{item.phone} • {item.email}</span>
                      </div>
                    </td>
                    <td>
                      <div className="course-name-cell">
                        <span style={{ color: '#e2e8f0' }}>{item.course_name}</span>
                        <span className="course-tag">{item.batch_name}</span>
                      </div>
                    </td>
                    <td>
                      <span className="amount-highlight font-semibold">{formatINR(item.amount_inr)}</span>
                    </td>
                    <td>
                      <span className="monospace font-bold" style={{ fontSize: '0.85rem' }}>{item.reference_id}</span>
                    </td>
                    <td>
                      {item.utr ? (
                        <span className="monospace" style={{ color: '#38bdf8', fontWeight: 600, fontSize: '0.85rem' }}>
                          {item.utr}
                        </span>
                      ) : (
                        <span style={{ color: '#64748b', fontSize: '0.8rem' }}>—</span>
                      )}
                    </td>
                    <td>{renderStatusBadge(item.payment_session_status)}</td>
                    <td>
                      <span style={{ color: '#94a3b8', fontSize: '0.8rem' }}>
                        {new Date(item.created_at).toLocaleString('en-IN', {
                          dateStyle: 'short',
                          timeStyle: 'short',
                        })}
                      </span>
                    </td>
                    <td style={{ textAlign: 'right' }}>
                      <button
                        onClick={() => onNavigate(`/upi/admin/payments/${item.payment_session_public_id}`)}
                        className="btn btn-sm btn-outline"
                        style={{ display: 'inline-flex', alignItems: 'center', gap: '4px' }}
                      >
                        <Eye size={13} />
                        <span>View Details</span>
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {/* Pagination Bar */}
        {totalPages > 1 && (
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '12px 20px', borderTop: '1px solid var(--border-color)', background: 'rgba(0, 0, 0, 0.15)' }}>
            <span style={{ fontSize: '0.8125rem', color: '#94a3b8' }}>
              Showing Page <strong style={{ color: '#e2e8f0' }}>{page}</strong> of <strong style={{ color: '#e2e8f0' }}>{totalPages}</strong> ({total} total items)
            </span>
            <div style={{ display: 'flex', gap: '6px' }}>
              <button
                onClick={() => setPage((p) => Math.max(1, p - 1))}
                disabled={page <= 1 || loading}
                className="btn btn-sm btn-outline"
              >
                <ChevronLeft size={14} />
                <span>Previous</span>
              </button>
              <button
                onClick={() => setPage((p) => Math.min(totalPages, p + 1))}
                disabled={page >= totalPages || loading}
                className="btn btn-sm btn-outline"
              >
                <span>Next</span>
                <ChevronRight size={14} />
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

/**
 * Protected route guard requiring active authenticated administrator.
 */

import React, { useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import { ShieldAlert, Loader2 } from 'lucide-react';

interface ProtectedRouteProps {
  children: React.ReactNode;
  onNavigate?: (path: string) => void;
}

export const ProtectedRoute: React.FC<ProtectedRouteProps> = ({ children, onNavigate }) => {
  const { isAuthenticated, isLoading } = useAuth();

  useEffect(() => {
    if (!isLoading && !isAuthenticated) {
      if (onNavigate) {
        onNavigate('/upi/admin/login');
      } else {
        window.history.pushState({}, '', '/upi/admin/login');
        window.dispatchEvent(new PopStateEvent('popstate'));
      }
    }
  }, [isLoading, isAuthenticated, onNavigate]);

  if (isLoading) {
    return (
      <div className="card loading-card" style={{ textAlign: 'center', padding: '3rem 1rem' }}>
        <Loader2 className="spinner" size={36} color="#818cf8" />
        <p style={{ marginTop: '1rem', color: '#94a3b8' }}>Verifying administrator session...</p>
      </div>
    );
  }

  if (!isAuthenticated) {
    return (
      <div className="card" style={{ textAlign: 'center', padding: '2rem 1rem' }}>
        <ShieldAlert size={40} color="#f87171" style={{ margin: '0 auto 1rem' }} />
        <h2 style={{ color: '#f87171', fontSize: '1.25rem', marginBottom: '0.5rem' }}>
          Authentication Required
        </h2>
        <p style={{ color: '#94a3b8', fontSize: '0.875rem' }}>
          Redirecting to administrator login...
        </p>
      </div>
    );
  }

  return <>{children}</>;
};

5/**
 * Authentication Context maintaining in-memory access token, admin profile,
 * and automatic session restoration on app initialization.
 */

import React, { createContext, useContext, useEffect, useState } from 'react';
import { AdminUser, AuthState } from '../types/auth';
import { getMeApi, loginApi, logoutAllApi, logoutApi, refreshApi } from '../services/apiClient';

interface AuthContextType extends AuthState {
  login: (email: string, password: string) => Promise<void>;
  logout: () => Promise<void>;
  logoutAll: () => Promise<void>;
  refreshSession: () => Promise<boolean>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [admin, setAdmin] = useState<AdminUser | null>(null);
  const [accessToken, setAccessTokenState] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState<boolean>(true);

  // Function to refresh session from HttpOnly cookie
  const refreshSession = async (): Promise<boolean> => {
    try {
      const response = await refreshApi();
      if (response && response.access_token) {
        setAccessTokenState(response.access_token);
        if (response.admin) {
          setAdmin(response.admin);
        } else {
          const profile = await getMeApi();
          setAdmin(profile);
        }
        return true;
      }
      setAdmin(null);
      setAccessTokenState(null);
      return false;
    } catch {
      setAdmin(null);
      setAccessTokenState(null);
      return false;
    }
  };

  // Restore session from HttpOnly refresh cookie on application mount
  useEffect(() => {
    let isMounted = true;

    async function initAuth() {
      await refreshSession();
      if (isMounted) {
        setIsLoading(false);
      }
    }

    initAuth();

    return () => {
      isMounted = false;
    };
  }, []);

  const login = async (email: string, password: string): Promise<void> => {
    setIsLoading(true);
    try {
      const response = await loginApi(email, password);
      setAccessTokenState(response.access_token);
      setAdmin(response.admin);
    } finally {
      setIsLoading(false);
    }
  };

  const logout = async (): Promise<void> => {
    setIsLoading(true);
    try {
      await logoutApi();
    } finally {
      setAdmin(null);
      setAccessTokenState(null);
      setIsLoading(false);
    }
  };

  const logoutAll = async (): Promise<void> => {
    setIsLoading(true);
    try {
      await logoutAllApi();
    } finally {
      setAdmin(null);
      setAccessTokenState(null);
      setIsLoading(false);
    }
  };

  const value: AuthContextType = {
    admin,
    accessToken,
    isAuthenticated: !!admin && !!accessToken,
    isLoading,
    login,
    logout,
    logoutAll,
    refreshSession,
  };

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
};

export function useAuth(): AuthContextType {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
}

/**
 * Application environment configuration
 */

export const config = {
  apiBaseUrl: import.meta.env.VITE_API_BASE_URL || '/upi-api',
  basePath: import.meta.env.VITE_BASE_PATH || '/upi/',
  appName: 'Samagra UPI Automation',
  isDev: import.meta.env.DEV,
};

import React, { useEffect, useState } from 'react';
import { AdminNav } from '../components/AdminNav';
import { getBatches, createBatch, updateBatch } from '../services/batchApi';
import { getCourses } from '../services/courseApi';
import { Batch, BatchStatus } from '../types/batch';
import { Course } from '../types/course';
import { config } from '../core/config';
import {
  Plus,
  Edit2,
  Archive,
  CheckCircle2,
  XCircle,
  AlertTriangle,
  Loader2,
  RefreshCw,
  Layers,
  X,
  Lock,
  Calendar,
  Copy,
  Check,
} from 'lucide-react';

interface AdminBatchesPageProps {
  onNavigate: (path: string) => void;
}

export const AdminBatchesPage: React.FC<AdminBatchesPageProps> = ({ onNavigate }) => {
  const [batches, setBatches] = useState<Batch[]>([]);
  const [courses, setCourses] = useState<Course[]>([]);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);
  const [copiedBatchId, setCopiedBatchId] = useState<string | null>(null);

  // URL-driven query params
  const getSearchParams = () => new URLSearchParams(window.location.search);
  const [selectedCourseFilter, setSelectedCourseFilter] = useState<string>(
    getSearchParams().get('course') || getSearchParams().get('course_public_id') || 'ALL'
  );
  const [statusFilter, setStatusFilter] = useState<string>(
    getSearchParams().get('status') || 'ALL'
  );

  // Modal States
  const [isCreateModalOpen, setIsCreateModalOpen] = useState(false);
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);
  const [batchToArchive, setBatchToArchive] = useState<Batch | null>(null);
  const [selectedBatch, setSelectedBatch] = useState<Batch | null>(null);

  // Form States
  const [formCourseId, setFormCourseId] = useState('');
  const [formName, setFormName] = useState('');
  const [formAmount, setFormAmount] = useState<string>('1000');
  const [formStartsAt, setFormStartsAt] = useState('');
  const [formEndsAt, setFormEndsAt] = useState('');
  const [formStatus, setFormStatus] = useState<'ACTIVE' | 'INACTIVE'>('ACTIVE');
  const [editStatus, setEditStatus] = useState<BatchStatus>('ACTIVE');
  const [formSubmitting, setFormSubmitting] = useState(false);
  const [formError, setFormError] = useState<string | null>(null);

  // Synchronize URL query params
  const updateUrlParams = (newCourse: string, newStatus: string) => {
    const params = new URLSearchParams();
    if (newCourse && newCourse !== 'ALL') {
      params.set('course', newCourse);
    }
    if (newStatus && newStatus !== 'ALL') {
      params.set('status', newStatus);
    }
    const query = params.toString();
    const newPath = query ? `${window.location.pathname}?${query}` : window.location.pathname;
    window.history.replaceState({}, '', newPath);
  };

  const handleCourseFilterChange = (val: string) => {
    setSelectedCourseFilter(val);
    updateUrlParams(val, statusFilter);
  };

  const handleStatusFilterChange = (val: string) => {
    setStatusFilter(val);
    updateUrlParams(selectedCourseFilter, val);
  };

  const loadData = async () => {
    setLoading(true);
    setError(null);
    try {
      const [coursesData, batchesData] = await Promise.all([
        getCourses(),
        getBatches(
          selectedCourseFilter === 'ALL' ? undefined : selectedCourseFilter,
          statusFilter === 'ALL' ? undefined : statusFilter
        ),
      ]);
      setCourses(coursesData);
      setBatches(batchesData);
    } catch (err: any) {
      setError(err.message || 'Failed to load batch data.');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadData();
  }, [selectedCourseFilter, statusFilter]);

  const openCreateModal = () => {
    const initialCourse = selectedCourseFilter !== 'ALL' ? selectedCourseFilter : courses[0]?.public_id || '';
    setFormCourseId(initialCourse);
    setFormName('');
    setFormAmount('2000');
    setFormStartsAt('');
    setFormEndsAt('');
    setFormStatus('ACTIVE');
    setFormError(null);
    setIsCreateModalOpen(true);
  };

  const handleCreateBatch = async (e: React.FormEvent) => {
    e.preventDefault();
    const cleanName = formName.trim();
    if (!cleanName) {
      setFormError('Batch name is required.');
      return;
    }
    if (!formCourseId) {
      setFormError('Please select a course for this batch.');
      return;
    }

    const amountNum = parseInt(formAmount, 10);
    if (isNaN(amountNum) || amountNum <= 0) {
      setFormError('Amount must be a positive whole INR value (e.g. 2000).');
      return;
    }

    if (formStartsAt && formEndsAt && formEndsAt < formStartsAt) {
      setFormError('End date must be on or after start date.');
      return;
    }

    setFormSubmitting(true);
    setFormError(null);
    try {
      await createBatch({
        course_public_id: formCourseId,
        name: cleanName,
        amount_inr: amountNum,
        status: formStatus,
        starts_at: formStartsAt ? new Date(formStartsAt).toISOString() : undefined,
        ends_at: formEndsAt ? new Date(formEndsAt).toISOString() : undefined,
      });
      setIsCreateModalOpen(false);
      await loadData();
    } catch (err: any) {
      setFormError(err.message || 'Failed to create batch.');
    } finally {
      setFormSubmitting(false);
    }
  };

  const openEditModal = (batch: Batch) => {
    setSelectedBatch(batch);
    setFormCourseId(batch.course_public_id);
    setFormName(batch.name);
    setFormAmount(String(batch.amount_inr));
    setFormStartsAt(batch.starts_at ? batch.starts_at.slice(0, 10) : '');
    setFormEndsAt(batch.ends_at ? batch.ends_at.slice(0, 10) : '');
    setEditStatus(batch.status);
    setFormError(null);
    setIsEditModalOpen(true);
  };

  const handleUpdateBatch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedBatch) return;

    const cleanName = formName.trim();
    if (!cleanName) {
      setFormError('Batch name is required.');
      return;
    }

    const amountNum = parseInt(formAmount, 10);
    if (isNaN(amountNum) || amountNum <= 0) {
      setFormError('Amount must be a positive whole INR value.');
      return;
    }

    if (formStartsAt && formEndsAt && formEndsAt < formStartsAt) {
      setFormError('End date must be on or after start date.');
      return;
    }

    setFormSubmitting(true);
    setFormError(null);
    try {
      await updateBatch(selectedBatch.public_id, {
        course_public_id: formCourseId !== selectedBatch.course_public_id ? formCourseId : undefined,
        name: cleanName,
        amount_inr: amountNum,
        status: editStatus,
        starts_at: formStartsAt ? new Date(formStartsAt).toISOString() : undefined,
        ends_at: formEndsAt ? new Date(formEndsAt).toISOString() : undefined,
      });
      setIsEditModalOpen(false);
      setSelectedBatch(null);
      await loadData();
    } catch (err: any) {
      setFormError(err.message || 'Failed to update batch.');
    } finally {
      setFormSubmitting(false);
    }
  };

  const handleQuickStatusChange = async (batch: Batch, targetStatus: BatchStatus) => {
    if (targetStatus === 'ARCHIVED') {
      setBatchToArchive(batch);
      return;
    }

    try {
      await updateBatch(batch.public_id, { status: targetStatus });
      await loadData();
    } catch (err: any) {
      alert(`Status update failed: ${err.message}`);
    }
  };

  const confirmArchiveBatch = async () => {
    if (!batchToArchive) return;
    setFormSubmitting(true);
    try {
      await updateBatch(batchToArchive.public_id, { status: 'ARCHIVED' });
      setBatchToArchive(null);
      await loadData();
    } catch (err: any) {
      alert(`Failed to archive batch: ${err.message}`);
    } finally {
      setFormSubmitting(false);
    }
  };

  const copyRegistrationLink = async (batch: Batch) => {
    const rawBasePath = config.basePath || '/upi/';
    const basePath = rawBasePath.endsWith('/') ? rawBasePath : `${rawBasePath}/`;
    const fullUrl = `${window.location.origin}${basePath}register/${batch.public_id}`;

    try {
      if (navigator.clipboard && navigator.clipboard.writeText) {
        await navigator.clipboard.writeText(fullUrl);
      } else {
        const textarea = document.createElement('textarea');
        textarea.value = fullUrl;
        document.body.appendChild(textarea);
        textarea.select();
        document.execCommand('copy');
        document.body.removeChild(textarea);
      }
      setCopiedBatchId(batch.public_id);
      setTimeout(() => setCopiedBatchId(null), 2500);
    } catch {
      alert(`Could not copy to clipboard. Link URL: ${fullUrl}`);
    }
  };

  const formatINR = (val: number) => {
    return new Intl.NumberFormat('en-IN', {
      style: 'currency',
      currency: 'INR',
      maximumFractionDigits: 0,
    }).format(val);
  };

  const getStatusBadge = (status: BatchStatus) => {
    switch (status) {
      case 'ACTIVE':
        return (
          <span className="status-pill active-pill">
            <CheckCircle2 size={12} /> Active
          </span>
        );
      case 'INACTIVE':
        return (
          <span className="status-pill inactive-pill">
            <XCircle size={12} /> Inactive
          </span>
        );
      case 'ARCHIVED':
        return (
          <span className="status-pill archived-pill">
            <Lock size={12} /> Archived
          </span>
        );
    }
  };

  return (
    <div className="admin-page-container">
      <AdminNav activeTab="batches" onNavigate={onNavigate} />

      <header className="page-header">
        <div>
          <h1 className="page-title">Batch & Cohort Management</h1>
          <p className="page-subtitle">Manage training cohort dates, fee amounts, and course assignments.</p>
        </div>
        <div className="page-actions">
          <button onClick={() => loadData()} disabled={loading} className="icon-btn" title="Refresh Batches">
            <RefreshCw size={16} className={loading ? 'spinner' : ''} />
          </button>
          <button onClick={openCreateModal} className="btn btn-primary">
            <Plus size={16} />
            <span>New Batch</span>
          </button>
        </div>
      </header>

      {/* Dual Filter Toolbar */}
      <div className="filter-toolbar card">
        <div className="filter-group">
          <label className="filter-label">Course:</label>
          <select
            value={selectedCourseFilter}
            onChange={(e) => handleCourseFilterChange(e.target.value)}
            className="filter-select"
          >
            <option value="ALL">All Courses</option>
            {courses.map((c) => (
              <option key={c.public_id} value={c.public_id}>
                {c.name} ({c.status})
              </option>
            ))}
          </select>
        </div>

        <div className="filter-group">
          <label className="filter-label">Status:</label>
          <div className="filter-pills">
            {['ALL', 'ACTIVE', 'INACTIVE', 'ARCHIVED'].map((st) => (
              <button
                key={st}
                className={`filter-pill ${statusFilter === st ? 'active' : ''}`}
                onClick={() => handleStatusFilterChange(st)}
              >
                {st}
              </button>
            ))}
          </div>
        </div>
      </div>

      {/* Main Content Area */}
      {loading ? (
        <div className="card loading-card">
          <Loader2 size={28} className="spinner" color="#818cf8" />
          <p style={{ marginTop: '0.75rem', color: 'var(--text-secondary)' }}>Loading batches...</p>
        </div>
      ) : error ? (
        <div className="card error-card">
          <AlertTriangle size={20} color="#ef4444" />
          <p>{error}</p>
          <button onClick={loadData} className="btn btn-sm btn-outline" style={{ marginTop: '0.75rem' }}>
            Try Again
          </button>
        </div>
      ) : batches.length === 0 ? (
        <div className="card empty-card">
          <Layers size={36} color="#6b7280" />
          <h3>No batches found</h3>
          <p>Create a cohort to begin configuring payments and schedules.</p>
          <button onClick={openCreateModal} className="btn btn-primary" style={{ marginTop: '1rem' }}>
            <Plus size={16} /> Create Batch
          </button>
        </div>
      ) : (
        <div className="table-responsive card">
          <table className="admin-table">
            <thead>
              <tr>
                <th>Batch Name</th>
                <th>Course</th>
                <th>Fee (INR)</th>
                <th>Schedule</th>
                <th>Status</th>
                <th style={{ textAlign: 'right' }}>Actions</th>
              </tr>
            </thead>
            <tbody>
              {batches.map((batch) => {
                const isArchived = batch.status === 'ARCHIVED';
                return (
                  <tr key={batch.public_id}>
                    <td>
                      <span className="font-semibold">{batch.name}</span>
                    </td>
                    <td>
                      <span className="course-tag">
                        {batch.course_name || 'Assigned Course'}
                      </span>
                    </td>
                    <td>
                      <span className="amount-highlight font-semibold monospace">
                        {formatINR(batch.amount_inr)}
                      </span>
                    </td>
                    <td>
                      <div className="date-cell text-sm">
                        {batch.starts_at || batch.ends_at ? (
                          <>
                            <Calendar size={13} color="#94a3b8" />
                            <span>
                              {batch.starts_at ? new Date(batch.starts_at).toLocaleDateString() : '—'}
                              {' to '}
                              {batch.ends_at ? new Date(batch.ends_at).toLocaleDateString() : '—'}
                            </span>
                          </>
                        ) : (
                          <span style={{ color: 'var(--text-muted)' }}>Self-paced / Open</span>
                        )}
                      </div>
                    </td>
                    <td>{getStatusBadge(batch.status)}</td>
                    <td>
                      <div className="table-actions">
                        {!isArchived ? (
                          <>
                            <button
                              onClick={() => copyRegistrationLink(batch)}
                              className="btn-action"
                              title={
                                batch.status === 'ACTIVE'
                                  ? 'Copy Public Registration Link'
                                  : 'Copy Registration Link (Note: Inactive batches display as unavailable to participants)'
                              }
                              style={{
                                color: copiedBatchId === batch.public_id ? '#34d399' : '#38bdf8',
                                borderColor: copiedBatchId === batch.public_id ? 'rgba(52, 211, 153, 0.4)' : undefined,
                              }}
                            >
                              {copiedBatchId === batch.public_id ? (
                                <>
                                  <Check size={14} color="#34d399" />
                                  <span style={{ color: '#34d399', fontWeight: 600 }}>Copied!</span>
                                </>
                              ) : (
                                <>
                                  <Copy size={14} color="#38bdf8" />
                                  <span>Copy Link</span>
                                </>
                              )}
                            </button>

                            <button
                              onClick={() => openEditModal(batch)}
                              className="btn-action"
                              title="Edit Batch"
                            >
                              <Edit2 size={15} color="#a5b4fc" />
                              <span>Edit</span>
                            </button>

                            {batch.status === 'ACTIVE' ? (
                              <button
                                onClick={() => handleQuickStatusChange(batch, 'INACTIVE')}
                                className="btn-action"
                                title="Deactivate Batch"
                              >
                                <XCircle size={15} color="#f59e0b" />
                                <span>Deactivate</span>
                              </button>
                            ) : (
                              <button
                                onClick={() => handleQuickStatusChange(batch, 'ACTIVE')}
                                className="btn-action"
                                title="Activate Batch"
                              >
                                <CheckCircle2 size={15} color="#10b981" />
                                <span>Activate</span>
                              </button>
                            )}

                            <button
                              onClick={() => handleQuickStatusChange(batch, 'ARCHIVED')}
                              className="btn-action btn-action-danger"
                              title="Archive Batch"
                            >
                              <Archive size={15} color="#ef4444" />
                              <span>Archive</span>
                            </button>
                          </>
                        ) : (
                          <span className="read-only-tag">Read-Only</span>
                        )}
                      </div>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}

      {/* Create Batch Modal */}
      {isCreateModalOpen && (
        <div className="modal-overlay">
          <div className="modal-card">
            <div className="modal-header">
              <h3>Create New Batch</h3>
              <button onClick={() => setIsCreateModalOpen(false)} className="icon-btn">
                <X size={18} />
              </button>
            </div>

            {formError && (
              <div className="error-banner">
                <AlertTriangle size={16} />
                <span>{formError}</span>
              </div>
            )}

            <form onSubmit={handleCreateBatch}>
              <div className="form-group">
                <label className="form-label">Associated Course *</label>
                <select
                  value={formCourseId}
                  onChange={(e) => setFormCourseId(e.target.value)}
                  required
                  className="form-input modal-input"
                  disabled={formSubmitting}
                >
                  <option value="" disabled>Select Course</option>
                  {courses
                    .filter((c) => c.status !== 'ARCHIVED')
                    .map((c) => (
                      <option key={c.public_id} value={c.public_id}>
                        {c.name} ({c.status})
                      </option>
                    ))}
                </select>
              </div>

              <div className="form-group">
                <label className="form-label">Batch / Cohort Title *</label>
                <input
                  type="text"
                  value={formName}
                  onChange={(e) => setFormName(e.target.value)}
                  placeholder="e.g. August 2026 Weekend"
                  required
                  className="form-input modal-input"
                  disabled={formSubmitting}
                />
              </div>

              <div className="form-group">
                <label className="form-label">Payment Amount (Whole INR ₹) *</label>
                <input
                  type="number"
                  min="1"
                  step="1"
                  value={formAmount}
                  onChange={(e) => setFormAmount(e.target.value)}
                  placeholder="2000"
                  required
                  className="form-input modal-input monospace"
                  disabled={formSubmitting}
                />
                <span className="field-hint">Specified in whole rupees (no paise or decimals).</span>
              </div>

              <div className="grid-2" style={{ marginBottom: '1.25rem' }}>
                <div>
                  <label className="form-label">Start Date (Optional)</label>
                  <input
                    type="date"
                    value={formStartsAt}
                    onChange={(e) => setFormStartsAt(e.target.value)}
                    className="form-input modal-input"
                    disabled={formSubmitting}
                  />
                </div>
                <div>
                  <label className="form-label">End Date (Optional)</label>
                  <input
                    type="date"
                    value={formEndsAt}
                    onChange={(e) => setFormEndsAt(e.target.value)}
                    className="form-input modal-input"
                    disabled={formSubmitting}
                  />
                </div>
              </div>

              <div className="form-group">
                <label className="form-label">Initial Status</label>
                <select
                  value={formStatus}
                  onChange={(e) => setFormStatus(e.target.value as 'ACTIVE' | 'INACTIVE')}
                  className="form-input modal-input"
                  disabled={formSubmitting}
                >
                  <option value="ACTIVE">ACTIVE (Published)</option>
                  <option value="INACTIVE">INACTIVE (Draft / Unpublished)</option>
                </select>
              </div>

              <div className="modal-footer">
                <button
                  type="button"
                  onClick={() => setIsCreateModalOpen(false)}
                  disabled={formSubmitting}
                  className="btn btn-outline"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  disabled={formSubmitting}
                  className="btn btn-primary"
                >
                  {formSubmitting ? 'Creating...' : 'Create Batch'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Edit Batch Modal */}
      {isEditModalOpen && selectedBatch && (
        <div className="modal-overlay">
          <div className="modal-card">
            <div className="modal-header">
              <h3>Edit Batch: {selectedBatch.name}</h3>
              <button onClick={() => setIsEditModalOpen(false)} className="icon-btn">
                <X size={18} />
              </button>
            </div>

            {formError && (
              <div className="error-banner">
                <AlertTriangle size={16} />
                <span>{formError}</span>
              </div>
            )}

            <form onSubmit={handleUpdateBatch}>
              <div className="form-group">
                <label className="form-label">Associated Course</label>
                <select
                  value={formCourseId}
                  onChange={(e) => setFormCourseId(e.target.value)}
                  className="form-input modal-input"
                  disabled={formSubmitting}
                >
                  {courses
                    .filter((c) => c.status !== 'ARCHIVED' || c.public_id === selectedBatch.course_public_id)
                    .map((c) => (
                      <option key={c.public_id} value={c.public_id}>
                        {c.name} {c.status === 'ARCHIVED' ? '(Archived)' : ''}
                      </option>
                    ))}
                </select>
                <span className="field-hint">Note: Reassignment is blocked if payment sessions exist.</span>
              </div>

              <div className="form-group">
                <label className="form-label">Batch Title *</label>
                <input
                  type="text"
                  value={formName}
                  onChange={(e) => setFormName(e.target.value)}
                  required
                  className="form-input modal-input"
                  disabled={formSubmitting}
                />
              </div>

              <div className="form-group">
                <label className="form-label">Fee Amount (Whole INR ₹) *</label>
                <input
                  type="number"
                  min="1"
                  step="1"
                  value={formAmount}
                  onChange={(e) => setFormAmount(e.target.value)}
                  required
                  className="form-input modal-input monospace"
                  disabled={formSubmitting}
                />
                <span className="field-hint">Existing historical payment sessions will preserve their original amount.</span>
              </div>

              <div className="grid-2" style={{ marginBottom: '1.25rem' }}>
                <div>
                  <label className="form-label">Start Date</label>
                  <input
                    type="date"
                    value={formStartsAt}
                    onChange={(e) => setFormStartsAt(e.target.value)}
                    className="form-input modal-input"
                    disabled={formSubmitting}
                  />
                </div>
                <div>
                  <label className="form-label">End Date</label>
                  <input
                    type="date"
                    value={formEndsAt}
                    onChange={(e) => setFormEndsAt(e.target.value)}
                    className="form-input modal-input"
                    disabled={formSubmitting}
                  />
                </div>
              </div>

              <div className="form-group">
                <label className="form-label">Lifecycle Status</label>
                <select
                  value={editStatus}
                  onChange={(e) => setEditStatus(e.target.value as BatchStatus)}
                  className="form-input modal-input"
                  disabled={formSubmitting}
                >
                  <option value="ACTIVE">ACTIVE</option>
                  <option value="INACTIVE">INACTIVE</option>
                  <option value="ARCHIVED">ARCHIVED (Terminal / Read-Only)</option>
                </select>
                {editStatus === 'ARCHIVED' && (
                  <p className="warning-hint">
                    Warning: Once archived, this cohort cannot be edited or reactivated.
                  </p>
                )}
              </div>

              <div className="modal-footer">
                <button
                  type="button"
                  onClick={() => setIsEditModalOpen(false)}
                  disabled={formSubmitting}
                  className="btn btn-outline"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  disabled={formSubmitting}
                  className="btn btn-primary"
                >
                  {formSubmitting ? 'Saving...' : 'Save Changes'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Batch Archive Confirmation Modal */}
      {batchToArchive && (
        <div className="modal-overlay">
          <div className="modal-card" style={{ maxWidth: '440px' }}>
            <div className="modal-header">
              <h3 style={{ display: 'flex', alignItems: 'center', gap: '8px', color: '#f87171' }}>
                <AlertTriangle size={20} />
                Archive Batch
              </h3>
              <button onClick={() => setBatchToArchive(null)} className="icon-btn">
                <X size={18} />
              </button>
            </div>

            <div style={{ padding: '12px 0 20px', color: 'var(--text-secondary)', fontSize: '0.925rem' }}>
              <p>
                Are you sure you want to archive <strong>{batchToArchive.name}</strong>?
              </p>
              <p style={{ marginTop: '10px', color: '#f87171', fontSize: '0.85rem', lineHeight: '1.4' }}>
                ⚠️ <strong>Archiving is permanent and terminal.</strong> Once archived, this batch becomes strictly read-only and cannot be reactivated or edited.
              </p>
            </div>

            <div className="modal-footer">
              <button
                type="button"
                onClick={() => setBatchToArchive(null)}
                disabled={formSubmitting}
                className="btn btn-outline"
              >
                Cancel
              </button>
              <button
                type="button"
                onClick={confirmArchiveBatch}
                disabled={formSubmitting}
                className="btn btn-danger"
                style={{ background: '#ef4444', borderColor: '#ef4444', color: '#ffffff' }}
              >
                {formSubmitting ? 'Archiving...' : 'Yes, Archive Batch'}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { AdminNav } from '../components/AdminNav';
import { getCourses, createCourse, updateCourse } from '../services/courseApi';
import { Course, CourseStatus } from '../types/course';
import {
  Plus,
  Edit2,
  Archive,
  CheckCircle2,
  XCircle,
  AlertTriangle,
  Loader2,
  RefreshCw,
  Layers,
  X,
  Lock,
} from 'lucide-react';

interface AdminCoursesPageProps {
  onNavigate: (path: string) => void;
}

export const AdminCoursesPage: React.FC<AdminCoursesPageProps> = ({ onNavigate }) => {
  const [courses, setCourses] = useState<Course[]>([]);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);
  const [statusFilter, setStatusFilter] = useState<string>('ALL');

  // Modal States
  const [isCreateModalOpen, setIsCreateModalOpen] = useState(false);
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);
  const [courseToArchive, setCourseToArchive] = useState<Course | null>(null);
  const [selectedCourse, setSelectedCourse] = useState<Course | null>(null);

  // Form States
  const [formName, setFormName] = useState('');
  const [formDescription, setFormDescription] = useState('');
  const [formStatus, setFormStatus] = useState<'ACTIVE' | 'INACTIVE'>('ACTIVE');
  const [editStatus, setEditStatus] = useState<CourseStatus>('ACTIVE');
  const [formSubmitting, setFormSubmitting] = useState(false);
  const [formError, setFormError] = useState<string | null>(null);

  const fetchCourseList = async () => {
    setLoading(true);
    setError(null);
    try {
      const filter = statusFilter === 'ALL' ? undefined : statusFilter;
      const data = await getCourses(filter);
      setCourses(data);
    } catch (err: any) {
      setError(err.message || 'Failed to load courses.');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchCourseList();
  }, [statusFilter]);

  const openCreateModal = () => {
    setFormName('');
    setFormDescription('');
    setFormStatus('ACTIVE');
    setFormError(null);
    setIsCreateModalOpen(true);
  };

  const handleCreateCourse = async (e: React.FormEvent) => {
    e.preventDefault();
    const cleanName = formName.trim();
    if (!cleanName) {
      setFormError('Course name is required.');
      return;
    }

    setFormSubmitting(true);
    setFormError(null);
    try {
      await createCourse({
        name: cleanName,
        description: formDescription.trim() || undefined,
        status: formStatus,
      });
      setIsCreateModalOpen(false);
      await fetchCourseList();
    } catch (err: any) {
      setFormError(err.message || 'Failed to create course.');
    } finally {
      setFormSubmitting(false);
    }
  };

  const openEditModal = (course: Course) => {
    setSelectedCourse(course);
    setFormName(course.name);
    setFormDescription(course.description || '');
    setEditStatus(course.status);
    setFormError(null);
    setIsEditModalOpen(true);
  };

  const handleUpdateCourse = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedCourse) return;

    const cleanName = formName.trim();
    if (!cleanName) {
      setFormError('Course name is required.');
      return;
    }

    setFormSubmitting(true);
    setFormError(null);
    try {
      await updateCourse(selectedCourse.public_id, {
        name: cleanName,
        description: formDescription.trim() || undefined,
        status: editStatus,
      });
      setIsEditModalOpen(false);
      setSelectedCourse(null);
      await fetchCourseList();
    } catch (err: any) {
      setFormError(err.message || 'Failed to update course.');
    } finally {
      setFormSubmitting(false);
    }
  };

  const handleQuickStatusChange = async (course: Course, targetStatus: CourseStatus) => {
    if (targetStatus === 'ARCHIVED') {
      setCourseToArchive(course);
      return;
    }

    try {
      await updateCourse(course.public_id, { status: targetStatus });
      await fetchCourseList();
    } catch (err: any) {
      alert(`Status update failed: ${err.message}`);
    }
  };

  const confirmArchiveCourse = async () => {
    if (!courseToArchive) return;
    setFormSubmitting(true);
    try {
      await updateCourse(courseToArchive.public_id, { status: 'ARCHIVED' });
      setCourseToArchive(null);
      await fetchCourseList();
    } catch (err: any) {
      alert(`Failed to archive course: ${err.message}`);
    } finally {
      setFormSubmitting(false);
    }
  };

  const getStatusBadge = (status: CourseStatus) => {
    switch (status) {
      case 'ACTIVE':
        return (
          <span className="status-pill active-pill">
            <CheckCircle2 size={12} /> Active
          </span>
        );
      case 'INACTIVE':
        return (
          <span className="status-pill inactive-pill">
            <XCircle size={12} /> Inactive
          </span>
        );
      case 'ARCHIVED':
        return (
          <span className="status-pill archived-pill">
            <Lock size={12} /> Archived
          </span>
        );
    }
  };

  return (
    <div className="admin-page-container">
      <AdminNav activeTab="courses" onNavigate={onNavigate} />

      <header className="page-header">
        <div>
          <h1 className="page-title">Course Management</h1>
          <p className="page-subtitle">Configure training programs, cohorts, and curricula.</p>
        </div>
        <div className="page-actions">
          <button
            onClick={() => fetchCourseList()}
            disabled={loading}
            className="icon-btn"
            title="Refresh Courses"
          >
            <RefreshCw size={16} className={loading ? 'spinner' : ''} />
          </button>
          <button onClick={openCreateModal} className="btn btn-primary">
            <Plus size={16} />
            <span>New Course</span>
          </button>
        </div>
      </header>

      {/* Filter Tabs */}
      <div className="filter-bar">
        <span className="filter-label">Filter by Status:</span>
        <div className="filter-pills">
          {['ALL', 'ACTIVE', 'INACTIVE', 'ARCHIVED'].map((st) => (
            <button
              key={st}
              className={`filter-pill ${statusFilter === st ? 'active' : ''}`}
              onClick={() => setStatusFilter(st)}
            >
              {st}
            </button>
          ))}
        </div>
      </div>

      {/* Main Content Area */}
      {loading ? (
        <div className="card loading-card">
          <Loader2 size={28} className="spinner" color="#818cf8" />
          <p style={{ marginTop: '0.75rem', color: 'var(--text-secondary)' }}>Loading courses...</p>
        </div>
      ) : error ? (
        <div className="card error-card">
          <AlertTriangle size={20} color="#ef4444" />
          <p>{error}</p>
          <button onClick={fetchCourseList} className="btn btn-sm btn-outline" style={{ marginTop: '0.75rem' }}>
            Try Again
          </button>
        </div>
      ) : courses.length === 0 ? (
        <div className="card empty-card">
          <Layers size={36} color="#6b7280" />
          <h3>No courses found</h3>
          <p>Get started by creating your first training program.</p>
          <button onClick={openCreateModal} className="btn btn-primary" style={{ marginTop: '1rem' }}>
            <Plus size={16} /> Create Course
          </button>
        </div>
      ) : (
        <div className="table-responsive card">
          <table className="admin-table">
            <thead>
              <tr>
                <th>Course Name</th>
                <th>Status</th>
                <th>Batches</th>
                <th>Created</th>
                <th style={{ textAlign: 'right' }}>Actions</th>
              </tr>
            </thead>
            <tbody>
              {courses.map((course) => {
                const isArchived = course.status === 'ARCHIVED';
                return (
                  <tr key={course.public_id}>
                    <td>
                      <div className="course-name-cell">
                        <span className="font-semibold">{course.name}</span>
                        {course.description && (
                          <span className="course-desc-preview">{course.description}</span>
                        )}
                      </div>
                    </td>
                    <td>{getStatusBadge(course.status)}</td>
                    <td>
                      <span className="count-badge" title="Total cohorts under this course">
                        {course.batch_count} {course.batch_count === 1 ? 'batch' : 'batches'}
                      </span>
                    </td>
                    <td className="monospace text-sm" style={{ color: 'var(--text-muted)' }}>
                      {new Date(course.created_at).toLocaleDateString()}
                    </td>
                    <td>
                      <div className="table-actions">
                        <button
                          onClick={() => onNavigate(`/upi/admin/batches?course=${course.public_id}`)}
                          className="btn-action"
                          title="View Batches for this course"
                        >
                          <Layers size={15} color="#38bdf8" />
                          <span>Batches</span>
                        </button>

                        {!isArchived ? (
                          <>
                            <button
                              onClick={() => openEditModal(course)}
                              className="btn-action"
                              title="Edit Course"
                            >
                              <Edit2 size={15} color="#a5b4fc" />
                              <span>Edit</span>
                            </button>

                            {course.status === 'ACTIVE' ? (
                              <button
                                onClick={() => handleQuickStatusChange(course, 'INACTIVE')}
                                className="btn-action"
                                title="Deactivate Course"
                              >
                                <XCircle size={15} color="#f59e0b" />
                                <span>Deactivate</span>
                              </button>
                            ) : (
                              <button
                                onClick={() => handleQuickStatusChange(course, 'ACTIVE')}
                                className="btn-action"
                                title="Activate Course"
                              >
                                <CheckCircle2 size={15} color="#10b981" />
                                <span>Activate</span>
                              </button>
                            )}

                            <button
                              onClick={() => handleQuickStatusChange(course, 'ARCHIVED')}
                              className="btn-action btn-action-danger"
                              title="Archive Course"
                            >
                              <Archive size={15} color="#ef4444" />
                              <span>Archive</span>
                            </button>
                          </>
                        ) : (
                          <span className="read-only-tag">Read-Only</span>
                        )}
                      </div>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}

      {/* Create Course Modal */}
      {isCreateModalOpen && (
        <div className="modal-overlay">
          <div className="modal-card">
            <div className="modal-header">
              <h3>Create New Course</h3>
              <button onClick={() => setIsCreateModalOpen(false)} className="icon-btn">
                <X size={18} />
              </button>
            </div>

            {formError && (
              <div className="error-banner">
                <AlertTriangle size={16} />
                <span>{formError}</span>
              </div>
            )}

            <form onSubmit={handleCreateCourse}>
              <div className="form-group">
                <label className="form-label">Course Title *</label>
                <input
                  type="text"
                  value={formName}
                  onChange={(e) => setFormName(e.target.value)}
                  placeholder="e.g. Applied Machine Learning"
                  required
                  className="form-input modal-input"
                  disabled={formSubmitting}
                />
              </div>

              <div className="form-group">
                <label className="form-label">Description (Optional)</label>
                <textarea
                  value={formDescription}
                  onChange={(e) => setFormDescription(e.target.value)}
                  placeholder="Overview of curriculum and objectives..."
                  rows={3}
                  className="form-input modal-input"
                  style={{ resize: 'vertical' }}
                  disabled={formSubmitting}
                />
              </div>

              <div className="form-group">
                <label className="form-label">Initial Status</label>
                <select
                  value={formStatus}
                  onChange={(e) => setFormStatus(e.target.value as 'ACTIVE' | 'INACTIVE')}
                  className="form-input modal-input"
                  disabled={formSubmitting}
                >
                  <option value="ACTIVE">ACTIVE (Published)</option>
                  <option value="INACTIVE">INACTIVE (Draft / Unpublished)</option>
                </select>
              </div>

              <div className="modal-footer">
                <button
                  type="button"
                  onClick={() => setIsCreateModalOpen(false)}
                  disabled={formSubmitting}
                  className="btn btn-outline"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  disabled={formSubmitting}
                  className="btn btn-primary"
                >
                  {formSubmitting ? 'Creating...' : 'Create Course'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Edit Course Modal */}
      {isEditModalOpen && selectedCourse && (
        <div className="modal-overlay">
          <div className="modal-card">
            <div className="modal-header">
              <h3>Edit Course: {selectedCourse.name}</h3>
              <button onClick={() => setIsEditModalOpen(false)} className="icon-btn">
                <X size={18} />
              </button>
            </div>

            {formError && (
              <div className="error-banner">
                <AlertTriangle size={16} />
                <span>{formError}</span>
              </div>
            )}

            <form onSubmit={handleUpdateCourse}>
              <div className="form-group">
                <label className="form-label">Course Title *</label>
                <input
                  type="text"
                  value={formName}
                  onChange={(e) => setFormName(e.target.value)}
                  required
                  className="form-input modal-input"
                  disabled={formSubmitting}
                />
              </div>

              <div className="form-group">
                <label className="form-label">Description</label>
                <textarea
                  value={formDescription}
                  onChange={(e) => setFormDescription(e.target.value)}
                  rows={3}
                  className="form-input modal-input"
                  style={{ resize: 'vertical' }}
                  disabled={formSubmitting}
                />
              </div>

              <div className="form-group">
                <label className="form-label">Lifecycle Status</label>
                <select
                  value={editStatus}
                  onChange={(e) => setEditStatus(e.target.value as CourseStatus)}
                  className="form-input modal-input"
                  disabled={formSubmitting}
                >
                  <option value="ACTIVE">ACTIVE</option>
                  <option value="INACTIVE">INACTIVE</option>
                  <option value="ARCHIVED">ARCHIVED (Terminal / Read-Only)</option>
                </select>
                {editStatus === 'ARCHIVED' && (
                  <p className="warning-hint">
                    Warning: Once archived, this course cannot be edited or reactivated.
                  </p>
                )}
              </div>

              <div className="modal-footer">
                <button
                  type="button"
                  onClick={() => setIsEditModalOpen(false)}
                  disabled={formSubmitting}
                  className="btn btn-outline"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  disabled={formSubmitting}
                  className="btn btn-primary"
                >
                  {formSubmitting ? 'Saving...' : 'Save Changes'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Archive Confirmation Modal */}
      {courseToArchive && (
        <div className="modal-overlay">
          <div className="modal-card" style={{ maxWidth: '440px' }}>
            <div className="modal-header">
              <h3 style={{ display: 'flex', alignItems: 'center', gap: '8px', color: '#f87171' }}>
                <AlertTriangle size={20} />
                Archive Course
              </h3>
              <button onClick={() => setCourseToArchive(null)} className="icon-btn">
                <X size={18} />
              </button>
            </div>

            <div style={{ padding: '12px 0 20px', color: 'var(--text-secondary)', fontSize: '0.925rem' }}>
              <p>
                Are you sure you want to archive <strong>{courseToArchive.name}</strong>?
              </p>
              <p style={{ marginTop: '10px', color: '#f87171', fontSize: '0.85rem', lineHeight: '1.4' }}>
                ⚠️ <strong>Archiving is permanent and terminal.</strong> Once archived, this course becomes strictly read-only and cannot be reactivated or edited.
              </p>
            </div>

            <div className="modal-footer">
              <button
                type="button"
                onClick={() => setCourseToArchive(null)}
                disabled={formSubmitting}
                className="btn btn-outline"
              >
                Cancel
              </button>
              <button
                type="button"
                onClick={confirmArchiveCourse}
                disabled={formSubmitting}
                className="btn btn-danger"
                style={{ background: '#ef4444', borderColor: '#ef4444', color: '#ffffff' }}
              >
                {formSubmitting ? 'Archiving...' : 'Yes, Archive Course'}
              </button>
            </div>
          </div>
