        );
      case 'REJECTED':
        return (
          <span className="status-pill" style={{ background: 'rgba(239, 68, 68, 0.15)', color: '#f87171', border: '1px solid rgba(239, 68, 68, 0.3)' }}>
            <XCircle size={12} /> Rejected
