  Lock,
  MessageCircle,
  QrCode,
  Send,
  ShieldCheck,
  User,
} from 'lucide-react';
import { fetchPaymentSession, submitPaymentSessionUTR } from '../services/publicApi';
import { PaymentSessionPublic } from '../types/public';

interface PublicPaymentPageProps {
  paymentSessionPublicId: string;
  onNavigate?: (path: string) => void;
}

export const PublicPaymentPage: React.FC<PublicPaymentPageProps> = ({
  paymentSessionPublicId,
  onNavigate,
}) => {
  const [loading, setLoading] = useState<boolean>(true);
  const [session, setSession] = useState<PaymentSessionPublic | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [copiedField, setCopiedField] = useState<'ref' | 'upi' | null>(null);

  // UTR Submission Form state (Phase 7)
  const [utrInput, setUtrInput] = useState<string>('');
  const [submitting, setSubmitting] = useState<boolean>(false);
  const [submitError, setSubmitError] = useState<string | null>(null);

  useEffect(() => {
    let isMounted = true;

    async function loadPaymentSession() {
      setLoading(true);
      setError(null);
      try {
        const data = await fetchPaymentSession(paymentSessionPublicId);
        if (isMounted) {
          setSession(data);
        }
      } catch (err: any) {
        if (isMounted) {
          setError(err.message || 'This payment session is no longer available.');
        }
      } finally {
        if (isMounted) {
          setLoading(false);
        }
      }
    }

    if (paymentSessionPublicId) {
      loadPaymentSession();
    } else {
      setError('Invalid payment session identifier.');
      setLoading(false);
    }

    return () => {
      isMounted = false;
    };
  }, [paymentSessionPublicId]);

  const formatINR = (val: number) => {
    return new Intl.NumberFormat('en-IN', {
      style: 'currency',
      currency: 'INR',
      maximumFractionDigits: 0,
    }).format(val);
  };

  const copyToClipboard = async (text: string, field: 'ref' | 'upi') => {
    try {
      if (navigator.clipboard && navigator.clipboard.writeText) {
        await navigator.clipboard.writeText(text);
      } else {
        const textarea = document.createElement('textarea');
        textarea.value = text;
        document.body.appendChild(textarea);
        textarea.select();
        document.execCommand('copy');
        document.body.removeChild(textarea);
      }
      setCopiedField(field);
      setTimeout(() => setCopiedField(null), 2500);
    } catch {
      alert(`Could not copy to clipboard. Text: ${text}`);
    }
  };

  const handleUTRSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const cleanUTR = utrInput.trim();
    if (!cleanUTR) {
      setSubmitError('Please enter your 12-digit transaction reference (UTR) number.');
      return;
    }
    if (cleanUTR.length < 4) {
      setSubmitError('Transaction reference (UTR) must be at least 4 characters long.');
      return;
    }

    if (!session) return;

    setSubmitting(true);
    setSubmitError(null);

    try {
      const response = await submitPaymentSessionUTR(session.public_id, cleanUTR);

      // Update session state to SUBMITTED
      setSession((prev) => {
        if (!prev) return prev;
        return {
          ...prev,
          status: 'SUBMITTED',
          utr_masked: response.utr_masked,
          submitted_at: response.submitted_at,
          whatsapp_url: response.whatsapp_url,
          submission_public_id: response.submission_public_id,
        };
      });

      // Attempt to open WhatsApp in a new tab
      if (response.whatsapp_url) {
        try {
          window.open(response.whatsapp_url, '_blank', 'noopener,noreferrer');
        } catch {
          // Graceful fallback: manual button remains available
        }
      }
    } catch (err: any) {
      setSubmitError(err.message || 'Unable to submit payment reference. Please try again.');
    } finally {
      setSubmitting(false);
    }
  };

  // 1. Loading State
  if (loading) {
    return (
      <div className="public-container">
        <div className="public-card loading-card">
          <Loader2 size={36} className="spinner" color="#818cf8" />
          <h2 style={{ marginTop: '1rem', color: '#f8fafc', fontSize: '1.25rem' }}>
            Loading Payment Checkout
          </h2>
          <p style={{ color: '#94a3b8', fontSize: '0.9rem', marginTop: '0.25rem' }}>
            Retrieving payment session details...
          </p>
        </div>
      </div>
    );
  }

  // 2. Error / Unavailable State
  if (error || !session) {
    return (
      <div className="public-container">
        <div className="public-card unavailable-card">
          <div className="icon-badge-danger">
            <AlertCircle size={32} color="#ef4444" />
          </div>
          <h1 className="unavailable-title">Payment Session Unavailable</h1>
          <p className="unavailable-subtitle">
            {error || 'This payment session could not be found or has expired.'}
          </p>
          <div className="unavailable-box">
            <HelpCircle size={18} color="#94a3b8" />
            <span>
              If you experienced an error or closed your registration prematurely, please return to the
              registration link to generate a fresh payment session.
            </span>
          </div>
          {onNavigate && (
            <button
              onClick={() => onNavigate('/')}
              className="btn btn-outline"
              style={{ marginTop: '1.5rem', width: '100%' }}
            >
              <ArrowLeft size={16} />
              <span>Back to Home</span>
            </button>
          )}
        </div>
      </div>
    );
  }

  // 3. Expired State
  if (session.is_expired || session.status === 'EXPIRED') {
    return (
      <div className="public-container">
        <div className="public-card unavailable-card">
          <div
            className="icon-badge-danger"
            style={{ background: 'rgba(245, 158, 11, 0.12)', borderColor: 'rgba(245, 158, 11, 0.3)' }}
          >
            <Clock size={32} color="#f59e0b" />
          </div>
          <h1 className="unavailable-title" style={{ color: '#fbbf24' }}>
            Payment Session Expired
          </h1>
          <p className="unavailable-subtitle">
            This payment session has exceeded its validity window. For security and financial accuracy,
            please generate a new checkout session.
          </p>
          <div className="summary-section" style={{ textAlign: 'left', marginBottom: '1.5rem' }}>
            <div className="summary-row">
              <span className="summary-label">Course</span>
              <span className="summary-val font-semibold">{session.course_name}</span>
            </div>
            <div className="summary-row">
              <span className="summary-label">Batch</span>
              <span className="summary-val">{session.batch_name}</span>
            </div>
            <div className="summary-row">
              <span className="summary-label">Participant</span>
              <span className="summary-val">{session.full_name}</span>
            </div>
          </div>
          {onNavigate && (
            <button
              onClick={() => onNavigate('/')}
              className="btn btn-primary"
              style={{ width: '100%' }}
            >
              <span>Return to Program Enrollment</span>
            </button>
          )}
        </div>
      </div>
    );
  }

  const isSubmitted = session.status === 'SUBMITTED';

  // 4. Active UPI Payment & UTR Submission Page
  return (
    <div className="public-container">
      <div className="public-card payment-checkout-card">
        {/* Header & Institute Branding */}
        <header className="public-header">
          <div className="institute-brand">
            <div className="brand-icon">
              <GraduationCap size={22} color="#818cf8" />
            </div>
            <div>
              <span className="brand-name">Samagra Institute</span>
              <span className="brand-tagline">Secure UPI Payment Checkout</span>
            </div>
          </div>
          {isSubmitted ? (
            <div className="status-pill status-pill-submitted">
              <CheckCircle2 size={13} color="#10b981" />
              <span>Payment Submitted</span>
            </div>
          ) : (
            <div className="status-pill active-pill" style={{ fontSize: '0.75rem', padding: '4px 10px' }}>
              <Clock size={12} />
              <span>Awaiting Payment</span>
            </div>
          )}
        </header>

        {/* Program & Participant Context */}
        <div className="payment-summary-box">
          <div className="payment-course-info">
            <h1 className="payment-course-title">{session.course_name}</h1>
            <span className="payment-batch-tag">{session.batch_name}</span>
          </div>

          <div className="payment-participant-row">
            <div className="participant-chip">
              <User size={13} color="#94a3b8" />
              <span>{session.full_name}</span>
            </div>
            <div className="payment-meta-badge">
              <ShieldCheck size={13} />
              <span>Verified Merchant</span>
            </div>
          </div>
        </div>

        {/* Amount Section */}
        <div className="amount-hero-banner">
          <span className="amount-label">Total Amount Payable</span>
          <span className="amount-val-hero">{formatINR(session.amount_inr)}</span>
        </div>

        {/* Dynamic UPI QR Code */}
        <div className="qr-code-section">
          <div className="qr-code-wrapper">
            <QRCodeSVG
              value={session.upi_uri}
              size={220}
              level="H"
              includeMargin={true}
              bgColor="#ffffff"
              fgColor="#0f172a"
              className="qr-svg-canvas"
            />
          </div>
          <div className="qr-instructions-badge">
            <QrCode size={14} />
            <span>Scan with any UPI App (GPay, PhonePe, Paytm, BHIM)</span>
          </div>
        </div>

        {/* Copyable Reference ID & UPI ID */}
        <div className="payment-keys-grid">
          {/* Reference ID */}
          <div className="payment-key-card">
            <div className="key-card-header">
              <span className="key-card-label">Payment Reference ID</span>
              <button
                onClick={() => copyToClipboard(session.reference_id, 'ref')}
                className="btn-copy-small"
                title="Copy Reference ID"
              >
                {copiedField === 'ref' ? (
                  <>
                    <Check size={12} color="#34d399" />
                    <span style={{ color: '#34d399' }}>Copied</span>
                  </>
                ) : (
                  <>
                    <Copy size={12} />
                    <span>Copy</span>
                  </>
                )}
              </button>
            </div>
            <span className="key-card-value monospace font-bold">{session.reference_id}</span>
          </div>

          {/* UPI ID */}
          <div className="payment-key-card">
            <div className="key-card-header">
              <span className="key-card-label">Payee UPI ID</span>
              <button
                onClick={() => copyToClipboard(session.upi_id, 'upi')}
                className="btn-copy-small"
                title="Copy UPI ID"
              >
                {copiedField === 'upi' ? (
                  <>
                    <Check size={12} color="#34d399" />
                    <span style={{ color: '#34d399' }}>Copied</span>
                  </>
                ) : (
                  <>
                    <Copy size={12} />
                    <span>Copy</span>
                  </>
                )}
              </button>
            </div>
            <span className="key-card-value monospace">{session.upi_id}</span>
          </div>
        </div>

        {/* Optional Mobile Deep Link */}
        <div style={{ marginTop: '1rem' }}>
          <a
            href={session.upi_uri}
            className="btn btn-outline upi-deep-link-btn"
            target="_blank"
            rel="noopener noreferrer"
          >
            <ExternalLink size={15} />
            <span>Pay directly via Installed UPI App</span>
          </a>
        </div>

        {/* Step-by-Step Payment Instructions */}
        <div className="instructions-card">
          <div className="instructions-header">
            <Info size={16} color="#818cf8" />
            <h3 className="instructions-title">Payment Instructions</h3>
          </div>
          <ol className="instructions-list">
            <li>
              Open your preferred UPI app (<strong>Google Pay, PhonePe, Paytm, or BHIM</strong>).
            </li>
            <li>
              Scan the QR code above or enter the Payee UPI ID <code>{session.upi_id}</code>.
            </li>
            <li>
              Verify that the payee is <strong>{session.payee_name}</strong> and fee is{' '}
              <strong>{formatINR(session.amount_inr)}</strong>.
            </li>
            <li>
              Complete the payment. Keep your <strong>12-digit UPI Reference (UTR) number</strong>{' '}
              safe from your transaction receipt.
            </li>
            <li>
              Enter the UTR number below to submit your payment details for verification.
            </li>
          </ol>
        </div>

        {/* ========================================================================= */}
        {/* PHASE 7: UTR SUBMISSION & WHATSAPP NOTIFICATION SECTION                    */}
        {/* ========================================================================= */}
        {isSubmitted ? (
          <div className="submitted-confirmation-card">
            <div className="submitted-icon-badge">
              <CheckCircle2 size={36} color="#10b981" />
            </div>
            <h2 className="submitted-title">Payment Details Submitted</h2>
            <p className="submitted-subtitle">
              Your transaction reference has been successfully submitted and is awaiting administrator verification.
            </p>

            <div className="submitted-meta-grid">
              <div className="submitted-meta-item">
                <span className="submitted-meta-label">Transaction Reference (UTR)</span>
                <span className="submitted-meta-val monospace font-bold">
                  {session.utr_masked || '••••'}
                </span>
              </div>
              <div className="submitted-meta-item">
                <span className="submitted-meta-label">Verification Status</span>
                <span className="submitted-meta-val status-tag-submitted">
                  SUBMITTED (Pending Review)
                </span>
              </div>
              {session.submitted_at && (
                <div className="submitted-meta-item submitted-meta-full">
                  <span className="submitted-meta-label">Submission Timestamp</span>
                  <span className="submitted-meta-val">
                    {new Date(session.submitted_at).toLocaleString('en-IN', {
                      dateStyle: 'medium',
                      timeStyle: 'short',
                    })}
                  </span>
                </div>
              )}
            </div>

            <div className="verification-notice-box">
              <Info size={16} color="#38bdf8" />
              <span>
                Your payment will be manually verified against institutional bank records. Once verified,
                you will receive enrollment confirmation.
              </span>
            </div>

            {session.whatsapp_url && (
              <div className="whatsapp-action-container">
                <a
                  href={session.whatsapp_url}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="btn btn-whatsapp"
                >
                  <MessageCircle size={18} />
                  <span>Notify Administrator on WhatsApp</span>
                </a>
                <p className="whatsapp-action-note">
                  Click above to open WhatsApp with your pre-filled payment details to notify the administrator.
                </p>
              </div>
            )}
          </div>
        ) : (
          <div className="utr-form-section">
            <div className="utr-form-header">
              <div className="utr-step-badge">Step 2</div>
              <div>
                <h3 className="utr-form-title">Submit Transaction Reference (UTR)</h3>
                <p className="utr-form-subtitle">
                  After completing your UPI payment, enter the 12-digit transaction reference number to submit.
                </p>
              </div>
            </div>

            {submitError && (
              <div className="form-error-banner" style={{ marginBottom: '1rem' }}>
                <AlertCircle size={16} />
                <span>{submitError}</span>
              </div>
            )}

            <form onSubmit={handleUTRSubmit} className="utr-form">
              <div className="form-group">
                <label className="form-label" htmlFor="utrInput">
                  UPI Reference / UTR Number <span className="required-star">*</span>
                </label>
                <input
                  id="utrInput"
                  type="text"
                  className={`form-input monospace ${submitError ? 'input-error' : ''}`}
                  placeholder="e.g. 123456789012"
                  value={utrInput}
                  onChange={(e) => {
                    setUtrInput(e.target.value);
                    if (submitError) setSubmitError(null);
                  }}
                  disabled={submitting}
                  maxLength={100}
                  autoComplete="off"
                  spellCheck={false}
                />
                <span className="form-hint">
                  Found on your transaction confirmation screen in Google Pay, PhonePe, Paytm, or BHIM.
                </span>
              </div>

              <button
                type="submit"
                className="btn btn-primary btn-submit-utr"
                disabled={submitting || !utrInput.trim()}
              >
                {submitting ? (
                  <>
                    <Loader2 size={16} className="spinner" />
                    <span>Submitting Reference...</span>
                  </>
                ) : (
                  <>
                    <Send size={16} />
                    <span>Submit Payment Reference</span>
                  </>
                )}
              </button>
            </form>
          </div>
        )}

        <div className="security-footer" style={{ marginTop: '1.5rem' }}>
          <Lock size={13} />
          <span>NPCI Unified Payments Interface Standard • End-to-End Encrypted</span>
        </div>
      </div>
    </div>
  );
};

/**
 * Public participant registration page for a shared batch link.
 * Route: /upi/register/:batchPublicId
 */

import React, { useEffect, useState } from 'react';
import {
  AlertCircle,
  Calendar,
  ChevronRight,
  GraduationCap,
  HelpCircle,
  Loader2,
  Lock,
  Mail,
  ShieldCheck,
  User,
} from 'lucide-react';
import { createPaymentSession, fetchPublicBatch } from '../services/publicApi';
import { FormErrors, ParticipantFormData, PublicBatch } from '../types/public';

interface PublicRegistrationPageProps {
  batchPublicId: string;
  onNavigate?: (path: string) => void;
}

const INDIAN_PHONE_REGEX = /^[6-9]\d{9}$/;
const EMAIL_REGEX = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

export const PublicRegistrationPage: React.FC<PublicRegistrationPageProps> = ({
  batchPublicId,
  onNavigate,
}) => {
  // Page states
  const [loading, setLoading] = useState<boolean>(true);
  const [unavailableError, setUnavailableError] = useState<string | null>(null);
  const [batch, setBatch] = useState<PublicBatch | null>(null);

  // Form states
  const [formData, setFormData] = useState<ParticipantFormData>({
    fullName: '',
    phone: '',
    email: '',
  });
  const [errors, setErrors] = useState<FormErrors>({});
  const [submitting, setSubmitting] = useState<boolean>(false);
  const [submissionError, setSubmissionError] = useState<string | null>(null);

  useEffect(() => {
    let isMounted = true;

    async function loadBatch() {
      setLoading(true);
      setUnavailableError(null);
      try {
        const data = await fetchPublicBatch(batchPublicId);
        if (isMounted) {
          setBatch(data);
        }
      } catch (err: any) {
        if (isMounted) {
          setUnavailableError(err.message || 'This registration link is no longer available.');
        }
      } finally {
        if (isMounted) {
          setLoading(false);
        }
      }
    }

    if (batchPublicId) {
      loadBatch();
    } else {
      setUnavailableError('Invalid registration link.');
      setLoading(false);
    }

    return () => {
      isMounted = false;
    };
  }, [batchPublicId]);

  const formatINR = (val: number) => {
    return new Intl.NumberFormat('en-IN', {
      style: 'currency',
      currency: 'INR',
      maximumFractionDigits: 0,
    }).format(val);
  };

  const validateField = (name: keyof ParticipantFormData, value: string): string | undefined => {
    switch (name) {
      case 'fullName': {
        const clean = value.trim();
        if (!clean) return 'Please enter your full name.';
        if (clean.length < 2) return 'Full name must be at least 2 characters.';
        if (clean.length > 255) return 'Full name cannot exceed 255 characters.';
        return undefined;
      }
      case 'phone': {
        let clean = value.replace(/[\s\-()]/g, '');
        if (clean.startsWith('+91')) clean = clean.slice(3);
        else if (clean.startsWith('91') && clean.length === 12) clean = clean.slice(2);
        else if (clean.startsWith('0') && clean.length === 11) clean = clean.slice(1);

        if (!clean) return 'Please enter your mobile number.';
        if (!INDIAN_PHONE_REGEX.test(clean)) {
          return 'Enter a valid 10-digit Indian mobile number (starts with 6-9).';
        }
        return undefined;
      }
      case 'email': {
        const clean = value.trim();
        if (!clean) return 'Please enter your email address.';
        if (!EMAIL_REGEX.test(clean)) return 'Please enter a valid email address.';
        return undefined;
      }
    }
  };

  const handleInputChange = (field: keyof ParticipantFormData, value: string) => {
    setFormData((prev) => ({ ...prev, [field]: value }));
    // Clear field-specific error as user types
    if (errors[field]) {
      setErrors((prev) => ({ ...prev, [field]: undefined }));
    }
  };

  const handleBlur = (field: keyof ParticipantFormData) => {
    const errorMsg = validateField(field, formData[field]);
    setErrors((prev) => ({ ...prev, [field]: errorMsg }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!batch) return;

    // Validate all fields
    const nameErr = validateField('fullName', formData.fullName);
    const phoneErr = validateField('phone', formData.phone);
    const emailErr = validateField('email', formData.email);

    if (nameErr || phoneErr || emailErr) {
      setErrors({
        fullName: nameErr,
        phone: phoneErr,
        email: emailErr,
      });
      return;
    }

    setSubmitting(true);
    setSubmissionError(null);

    try {
      const session = await createPaymentSession(batch.public_id, formData);
      const targetPath = `/upi/payment/${session.public_id}`;
      if (onNavigate) {
        onNavigate(targetPath);
      } else {
        window.history.pushState({}, '', targetPath);
        window.location.pathname = targetPath;
      }
    } catch (err: any) {
      setSubmissionError(err.message || 'Unable to create payment session. Please try again.');
    } finally {
      setSubmitting(false);
    }
  };

  // 1. Loading State
  if (loading) {
    return (
      <div className="public-container">
        <div className="public-card loading-card">
          <Loader2 size={36} className="spinner" color="#818cf8" />
          <h2 style={{ marginTop: '1rem', color: '#f8fafc', fontSize: '1.25rem' }}>
            Loading Registration Details
          </h2>
          <p style={{ color: '#94a3b8', fontSize: '0.9rem', marginTop: '0.25rem' }}>
            Resolving program details and cohort schedule...
          </p>
        </div>
      </div>
    );
  }

  // 2. Unavailable State (404 / Inactive / Archived)
  if (unavailableError || !batch) {
    return (
      <div className="public-container">
        <div className="public-card unavailable-card">
          <div className="icon-badge-danger">
            <AlertCircle size={32} color="#ef4444" />
          </div>
          <h1 className="unavailable-title">Registration Unavailable</h1>
          <p className="unavailable-subtitle">
            {unavailableError || 'This registration link is no longer active.'}
          </p>
          <div className="unavailable-box">
            <HelpCircle size={18} color="#94a3b8" />
            <span>
              If you believe this is an error, please contact the training coordinator or program
              administrator for an updated link.
            </span>
          </div>
        </div>
      </div>
    );
  }

  // 3. Available Registration Form State
  return (
    <div className="public-container">
      <div className="public-card">
        {/* Header & Institute Branding */}
        <header className="public-header">
          <div className="institute-brand">
            <div className="brand-icon">
              <GraduationCap size={22} color="#818cf8" />
            </div>
            <div>
              <span className="brand-name">Samagra Institute</span>
              <span className="brand-tagline">Program Enrollment Portal</span>
            </div>
          </div>
        </header>

        {/* Read-Only Course & Batch Context */}
        <div className="program-hero-card">
          <div className="program-meta-badge">
            <ShieldCheck size={13} />
            <span>Verified Cohort Link</span>
          </div>

          <h1 className="program-title">{batch.course_name}</h1>
          <div className="program-batch-pill">
            <span>{batch.batch_name}</span>
          </div>

          <div className="program-details-grid">
            <div className="program-detail-item">
              <span className="detail-label">Training Fee</span>
              <span className="detail-val fee-val">{formatINR(batch.amount_inr)}</span>
            </div>

            <div className="program-detail-item">
              <span className="detail-label">Schedule</span>
              <span className="detail-val schedule-val">
                {batch.starts_at || batch.ends_at ? (
                  <>
                    <Calendar size={13} style={{ display: 'inline', marginRight: '4px' }} />
                    {batch.starts_at ? new Date(batch.starts_at).toLocaleDateString() : '—'}
                    {batch.ends_at ? ` to ${new Date(batch.ends_at).toLocaleDateString()}` : ''}
                  </>
                ) : (
                  'Flexible / Immediate Access'
                )}
              </span>
            </div>
          </div>
        </div>

        {/* Participant Registration Form */}
        <div className="registration-form-section">
          <h2 className="form-section-title">Participant Information</h2>
          <p className="form-section-subtitle">
            Please enter your contact details. Confirmations will be sent via Email & SMS.
          </p>

          {submissionError && (
            <div className="error-banner" style={{ marginBottom: '1.25rem' }}>
              <AlertCircle size={16} />
              <span>{submissionError}</span>
            </div>
          )}

          <form onSubmit={handleSubmit} noValidate>
            {/* Full Name */}
            <div className="form-group">
              <label htmlFor="reg-fullname" className="form-label">
                Full Name <span style={{ color: '#ef4444' }}>*</span>
              </label>
              <div className="input-with-icon">
                <User size={16} className="input-icon" />
                <input
                  id="reg-fullname"
                  type="text"
                  placeholder="e.g. Anand J Nair"
                  value={formData.fullName}
                  onChange={(e) => handleInputChange('fullName', e.target.value)}
                  onBlur={() => handleBlur('fullName')}
                  className={`form-input public-input ${errors.fullName ? 'input-error' : ''}`}
                  disabled={submitting}
                  autoComplete="name"
                />
              </div>
              {errors.fullName && <p className="field-error-text">{errors.fullName}</p>}
            </div>

            {/* Mobile Number */}
            <div className="form-group">
              <label htmlFor="reg-phone" className="form-label">
                Mobile Number (India) <span style={{ color: '#ef4444' }}>*</span>
              </label>
              <div className="input-with-prefix">
                <span className="input-prefix">+91</span>
                <input
                  id="reg-phone"
                  type="tel"
                  placeholder="9876543210"
                  maxLength={10}
                  value={formData.phone}
                  onChange={(e) => {
                    const onlyNums = e.target.value.replace(/\D/g, '');
                    handleInputChange('phone', onlyNums);
                  }}
                  onBlur={() => handleBlur('phone')}
                  className={`form-input public-input ${errors.phone ? 'input-error' : ''}`}
                  disabled={submitting}
                  autoComplete="tel"
                />
              </div>
              {errors.phone && <p className="field-error-text">{errors.phone}</p>}
            </div>

            {/* Email Address */}
            <div className="form-group">
              <label htmlFor="reg-email" className="form-label">
                Email Address <span style={{ color: '#ef4444' }}>*</span>
              </label>
              <div className="input-with-icon">
                <Mail size={16} className="input-icon" />
                <input
                  id="reg-email"
                  type="email"
                  placeholder="you@example.com"
                  value={formData.email}
                  onChange={(e) => handleInputChange('email', e.target.value)}
                  onBlur={() => handleBlur('email')}
                  className={`form-input public-input ${errors.email ? 'input-error' : ''}`}
                  disabled={submitting}
                  autoComplete="email"
                />
              </div>
              {errors.email && <p className="field-error-text">{errors.email}</p>}
            </div>

            {/* CTA Button */}
            <button
              type="submit"
              disabled={submitting}
              className="btn btn-primary public-submit-btn"
            >
              {submitting ? (
                <>
                  <Loader2 size={18} className="spinner" />
                  <span>Initiating UPI Checkout...</span>
                </>
              ) : (
                <>
                  <span>Continue to Pay</span>
                  <ChevronRight size={18} />
                </>
              )}
            </button>

            <div className="security-footer">
              <Lock size={13} />
              <span>Safe & Secure UPI Payment Gateway Authorization</span>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
};

